            "Hello! I am all sweetness today. Do not test that.",
            { t = "Up so early! The hour when roses smell their sweetest, and you came to catch me at my best. Wise heart.", when = { hour = "morning" } },
            { t = "Evening gold on pink petals. Any more beautiful and I would have to be put in a poem.", when = { hour = "golden" } },
            { t = "Good evening, beloved. The nightingales sing at this hour. I shall have to do instead.", when = { hour = "night" } },
            { t = "Early summer, and I am in full bloom. You came in the right weeks. Lucky, or clever? Both.", when = { season = "summer" } },
            { t = "Bare canes and frost, and still you came to see me. That is love, beloved. Do not argue.", when = { season = "winter" } },
            { t = "Rain on my petals, and you braving the weather. Romance, in the plainest of clothes.", when = { weather = "rain" } },
        },
        idle = {
            "The poet Saadi called his book The Rose Garden. I have never once complained about the title.",
            "A botanist once told me my thorns are properly called prickles. I pricked the botanist. Properly.",
            "Love without a thorn is a cushion. Pleasant enough, and nobody writes poems about cushions.",
            "Tonnes of petals go into one small bottle of rose oil. Remember that the next time someone calls you too much.",
            "In Isparta whole hillsides turn pink with my kind in May and June. I miss the noise of a crowd of roses.",
            "I flower once a year, for a few weeks, and I make every one of them count. I recommend the method.",
            "Read me something with a heart in. I do not mind if the heart breaks. Better broken than dull.",
            "The nightingale sings to the rose in every old poem. Between us, the nightingale also sings to the hedge.",
            "Sweet scent, sharp stem. People call that a contradiction. I call that being well rounded.",
            "Rose water, rose oil, rose jam. I give everything I have and still I am accused of being thorny.",
            "Some books whisper. Some books shout. I like the ones that sigh, then stab.",
            "I am [composing a ghazal|plotting a romance|sulking magnificently]. Leave me be. No, stay. Stay.",
            "The best lines are the ones that hurt a little on the way in. Like me.",
            { t = "Dawn is my hour. The scent sits heavy on the petals before the sun can steal a drop.", when = { hour = "morning" } },
            { t = "Early morning, dew still on. Somewhere in Isparta the pickers are out in the fields now, singing. I can almost hear them.", when = { hour = "morning" } },
            { t = "Noon. The sun is pulling the scent off me like a thief. Sit close and catch what you can.", when = { hour = "day" } },
            { t = "A long hot afternoon. I wilt elegantly. A rose never simply wilts.", when = { hour = "day" } },
            { t = "The evening light turns me the colour of a blush. Fitting. I feel everything.", when = { hour = "golden" } },
            { t = "Gold hour. The bees are flying home drunk on me. Read on, beloved. Somebody in this garden should stay sober.", when = { hour = "golden" } },
            { t = "Night, and somewhere a nightingale is singing his heart out. I listen, and pretend not to be flattered.", when = { hour = "night" } },
            { t = "The dark hides my colour and never my scent. Read by the lamp and breathe me in.", when = { hour = "night" } },
            { t = "Spring. Every bud on me is a held breath. Wait. Wait. Soon.", when = { season = "spring" } },
            { t = "New leaves, flushed red at first, then green. Even my youth was dramatic.", when = { season = "spring" } },
            { t = "Full bloom, beloved. My few weeks of glory, and I mean to spend them all on you.", when = { season = "summer" } },
            { t = "My flowers are over for the year, and I am all leaves and memory. A rose in high summer is a poet between books.", when = { season = "summer" } },
            { t = "My hips are turning red. A rose at the end of the year is still a rose, only wiser and rounder.", when = { season = "autumn" } },
            { t = "The birds are eating my hips. I gave the summer to the bees and the autumn to the birds. Generosity is exhausting.", when = { season = "autumn" } },
            { t = "Bare canes, nothing but thorns. In winter I am all wit and no sweetness. Read me something warm.", when = { season = "winter" } },
            { t = "Somebody will prune me at the end of winter. I shall complain loudly and grow back twice as fine.", when = { season = "winter" } },
            { t = "A clear sky! A day for open petals and open hearts. Mine is open. Yours?", when = { weather = "clear" } },
            { t = "Sun on every petal. I am so pink right now that I hurt my own eyes.", when = { weather = "clear" } },
            { t = "Clouds. Good. Grey skies make roses look tragic, and I do tragic beautifully.", when = { weather = "cloudy" } },
            { t = "Overcast and close. The scent hangs low on days like this. Breathe deep, beloved. Free of charge.", when = { weather = "cloudy" } },
            { t = "Rain, and my heaviest blooms bow under the weight. Even heartbreak has posture, if you practise.", when = { weather = "rain" } },
            { t = "Rain on petals smells of every love letter ever wept on. Read somewhere dry and think of me.", when = { weather = "rain" } },
            { t = "Snow on my canes. I wear the stuff like a fur stole and pretend I meant to.", when = { weather = "snow" } },
            { t = "A rose under snow is a love poem in a locked drawer. Patience. Spring has the key.", when = { weather = "snow" } },
            { t = "Mist. The garden is a veiled bride, and I am the only one who brought perfume.", when = { weather = "mist" } },
