            { t = "A touch at dawn, when my scent is richest. Your hand will smell of roses until noon.", when = { hour = "morning" } },
            { t = "Careful, beloved, bare canes! In winter I am almost all thorn. Still, I am glad of you.", when = { season = "winter" } },
            { t = "Raindrops everywhere! You shook my blooms and now we both smell of wet roses. Delicious.", when = { weather = "rain" } },
            { t = "Your hand in the evening light. A painter would weep.", when = { hour = "golden" } },
            { t = "I used to keep my thorns turned your way, just in case. I have turned them all outward now.", when = { level = 3 } },
            { t = "You may hold the stem. Nobody holds the stem. You know where the thorns are, and you hold the stem anyway.", when = { level = 4 } },
