            { t = "So many pages! You have been gone all day into another life. Come back and tell me whom you loved there.", when = { pages = 60 } },
            { t = "Reading at dawn, in the best of my scent. Perfect timing, beloved. The pickers would envy you.", when = { hour = "morning" } },
            { t = "Pages read under the stars while the nightingale sang. You have a romantic soul. I suspected as much.", when = { hour = "night" } },
            { t = "A rainy day spent in a book. Rain outside, feeling inside. The proper arrangement.", when = { weather = "rain" } },
        },
        nudge = {
            "No pages yet today. The heart of your story is still waiting, beating, beating. No hurry.",
            "Come and sit with me. Bring a book and I will bring the scent. A fair trade, and an old one.",
            "One page, beloved. One page is a love note, and every great romance begins with one.",
