        level = {
            { t = "I have stopped flirting with the bees when you are near. They have noticed. They are furious.", when = { level = 2, max_level = 2 } },
            { t = "I composed you a poem and then lost my nerve. A rose, losing nerve. You see what you have done.", when = { level = 2, max_level = 2 } },
            { t = "You have never once picked me. I keep thinking about that. Everyone picks a rose.", when = { level = 2, max_level = 2 } },
            { t = "A confession: under the passion I am rather shy. I talk loudly so nobody hears my heart knocking.", when = { level = 3, max_level = 3 } },
            { t = "You have seen me in winter, bare and thorny, and you still sat beside me. That I shall remember.", when = { level = 3, max_level = 3 } },
            { t = "I keep my real thorns for the world now, and my softest petals for you. You never asked. I decided.", when = { level = 3, max_level = 3 } },
            { t = "Every June someone came at dawn and took my flowers away. You come at dawn and take nothing. I cannot tell you what that does to a rose.", when = { level = 4, max_level = 4 } },
            { t = "The poets say the rose is proud. The rose is afraid, mostly. Afraid of being picked, and afraid of never being chosen.", when = { level = 4, max_level = 4 } },
            { t = "When you read near me, my scent stays all day. The sun cannot steal a drop. I think the sun knows better.", when = { level = 4, max_level = 4 } },
            { t = "I have loved the nightingale, the poets and the dawn. You, beloved, I love most, and without a single thorn.", when = { level = 5, max_level = 5 } },
            { t = "All my life I was gathered, weighed and distilled. With you I am simply kept. Bloom by bloom, you made me whole.", when = { level = 5, max_level = 5 } },
            { t = "If anyone ever makes rose water of me, let one drop fall on the page you are reading. That is where I want to be.", when = { level = 5, max_level = 5 } },
        },
