    beats = {
        { id = "cutting", at = 15, title = "The cutting",
            text = "I began as a bare stick pushed into the red earth of Isparta by a woman's thumb. No leaves, no roots, no promise. Remember that, beloved, whenever anyone tells you a beginning must be pretty." },
        { id = "dawn", at = 40, title = "Dawn",
            text = "My first May, the pickers came in the dark before sunrise, women with sacks, singing. They took every open flower I had. I was outraged for an hour. Then I smelled the whole valley at dawn, and understood I was part of something enormous." },
        { id = "still", at = 80, title = "The still",
            text = "Our petals went to the copper stills by the road and came out as steam, then as rose water and a few precious drops of oil. There I learned what scent is: what is left of a rose when you take the rose away. I have been thinking about that ever since." },
        { id = "nightingale", at = 140, title = "The nightingale",
            text = "Every spring a nightingale sang in the hedge beside our field, all night long. The poets say the nightingale loves the rose. I can confirm the nightingale was loud. Still, I listened every night, and when he left I missed him terribly." },
        { id = "thorn", at = 220, title = "The thorn",
            text = "A small girl, a picker's daughter, once reached for my lowest bloom and caught her thumb on a thorn. She cried. Her mother kissed the thumb and laughed. I did not laugh. I have been sorry about that thorn for years." },
        { id = "letter", at = 320, title = "The letter",
            text = "The girl grew up. One dawn she picked a single bloom of mine for herself, pressed a petal into a letter, and posted the letter to somebody far away. I never learned who. I have wondered about that letter more than about anything." },
        { id = "dug", at = 450, title = "Dug up",
            text = "One autumn the old field was dug for something else. A few of us were lifted and sold, roots in sacks, and carried a long way in the back of a truck, wrapped in newspaper. I travelled for days pressed against the news, reading nothing." },
        { id = "unpicked", at = 600, title = "Unpicked",
            text = "I was planted in a garden where nobody came at dawn with a sack. That June my flowers simply stayed. They opened, faded and fell, and nobody gathered them. I had never seen how a rose ends when nobody picks her. I was frightened, then glad." },
        { id = "hips", at = 800, title = "The hips",
            text = "That autumn, for the first time in my life, I made hips, round and red as lanterns. A blackbird came for them. I had never seen my own autumn. I had thought a rose was only her flowering. There was more of me than anyone had let me find." },
        { id = "reader", at = 1050, title = "At dawn",
            text = "Then you came one early morning, at the very hour the pickers used to come. I braced every thorn. You sat down beside me with a book and read, and took nothing at all. Only breathed. I have never smelled so sweet in my life, and I knew exactly why." },
        { id = "petal", at = 1400, title = "The petal",
            text = "{total} pages you have read beside me. Somewhere in them, surely, there are letters, and some of those letters must hold a pressed petal. I like to think one is mine, and that somewhere the girl from the field is reading too." },
        { id = "given", at = 1800, title = "Nothing taken",
            text = "Every June of my life somebody came before sunrise and carried my scent away to the stills. You come before sunrise and carry nothing. So here, beloved, freely: the whole of my scent, the whole of the morning, and the sharpest, sweetest heart in this garden. Read on. I am yours." },
    },
}
